        context=harness.build_context(),
    )

    assert captured["params"]["account_id"] == "ops-bot"

import { afterEach, describe, expect, it, vi } from 'vitest';
import { createBrowserAgent } from '../browserAgentApi';

afterEach(() => vi.unstubAllGlobals());

describe('saved Browser Agent creation', () => {
  it('retries a lost response with the same mutation identity and tool selection', async () => {
    const result = { node_ids: { agent: '7:browser_agent:1' }, operations: [] };
    const fetch = vi.fn().mockRejectedValueOnce(new TypeError('Lost response'))
      .mockResolvedValueOnce(new Response(JSON.stringify(result)));
    vi.stubGlobal('fetch', fetch);
    expect(await createBrowserAgent({ workflow_id: '7', browser_node_id: '7:browser:1' })).toEqual(result);
    expect(fetch).toHaveBeenCalledTimes(2);
    const first = fetch.mock.calls[0][1];
    expect(fetch.mock.calls[1][1].body).toBe(first.body);
    expect(first.credentials).toBe('include');
    expect(JSON.parse(first.body)).toMatchObject({ workflow_id: '7', browser_node_id: '7:browser:1', mutation_id: expect.any(String) });
  });

  it('surfaces a server rejection without submitting a second mutation', async () => {
    const fetch = vi.fn().mockResolvedValue(new Response(JSON.stringify({ detail: 'Browser access denied' }), { status: 404 }));
    vi.stubGlobal('fetch', fetch);
    await expect(createBrowserAgent({ workflow_id: '7' })).rejects.toThrow('Browser access denied');
    expect(fetch).toHaveBeenCalledTimes(1);
  });
});

/**
 * workflowApi.saveWorkflow answers null when nothing was saved and tells
 * `onFailure` why, so the store can show the reason instead of only logging
 * that the save failed.
 */

import { describe, it, expect, vi, afterEach } from 'vitest';
import { workflowApi } from '../workflowApi';

const graph = { nodes: [], edges: [] };

function answer(body: unknown) {
  vi.stubGlobal('fetch', vi.fn(async () => ({ json: async () => body })));
}

afterEach(() => {
  vi.unstubAllGlobals();
  vi.restoreAllMocks();
});

describe('workflowApi.saveWorkflow', () => {
  it('passes the messages of a refused save to onFailure', async () => {
    answer({
      success: false,
      error: 'invalid_context_topology',
      validation_errors: [
        { code: 'SHARED_CONTEXT', message: 'A Context node cannot serve multiple agents' },
        { code: 'WITHOUT_MESSAGE' },
      ],
    });
    const onFailure = vi.fn();

    await expect(workflowApi.saveWorkflow('7', 'Maya', graph, onFailure)).resolves.toBeNull();

    expect(onFailure).toHaveBeenCalledWith({
      error: 'invalid_context_topology',
      messages: ['A Context node cannot serve multiple agents'],
    });
  });

  it('reports a request that never completed as unreachable', async () => {
    vi.stubGlobal('fetch', vi.fn(async () => {
      throw new TypeError('Failed to fetch');
    }));
    vi.spyOn(console, 'error').mockImplementation(() => {});
    const onFailure = vi.fn();

    await expect(workflowApi.saveWorkflow('7', 'Maya', graph, onFailure)).resolves.toBeNull();

    expect(onFailure).toHaveBeenCalledWith({ error: 'unreachable', messages: [] });
  });

  it('reports nothing when the save succeeds', async () => {
    answer({ success: true, id: '7', slug: 'Maya_1', data: graph });
    const onFailure = vi.fn();

    const result = await workflowApi.saveWorkflow('7', 'Maya', graph, onFailure);

    expect(result?.id).toBe('7');
    expect(onFailure).not.toHaveBeenCalled();
  });
